<?php $version='RoadDiscover Remote GPS';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title><?=$version?></title><style>:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color-scheme:dark}body{margin:0;background:#0d1f24;color:#fff;min-height:100vh;display:grid;place-items:center;padding:1rem}main{width:min(520px,100%);background:#153039;border-radius:18px;padding:1.25rem}h1{margin:.2rem 0}.muted{color:#b8c8cd;line-height:1.45}label{display:grid;gap:.4rem;margin:1rem 0;font-weight:700}input{font:inherit;padding:.8rem;border-radius:10px;border:1px solid #587078;background:#fff;color:#111}.actions{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}button{font:inherit;border:0;border-radius:10px;padding:1rem;font-weight:800}#start{background:#17a69f;color:#fff}#stop{background:#b84a4a;color:#fff}button:disabled{opacity:.45}.status{padding:.9rem;background:rgba(255,255,255,.08);border-radius:10px;margin-top:1rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:.7rem;margin-top:1rem}.readout{background:rgba(255,255,255,.06);border-radius:10px;padding:.8rem}.readout span{display:block;color:#b8c8cd;font-size:.75rem}.readout strong{display:block;margin-top:.2rem}.ok{color:#8ee8c3}.bad{color:#ffb3b3}.warning{padding:.8rem;border:1px solid #d3a94a;border-radius:10px;color:#ffe3a0;font-size:.85rem}</style></head><body><main><div class="muted">RoadDiscover</div><h1><?=$version?></h1><p class="muted">This phone can be anywhere with Internet access. GPS is sent securely to the RDL computer and automatically recorded for later replay.</p><p class="warning"><strong>Driver safety:</strong> set this up before driving. Do not operate or look at this page while the vehicle is moving. Keep the phone powered and this page open.</p><label>Session code<input id="session" value="roadtest" maxlength="32" autocapitalize="none" autocomplete="off"></label><div class="actions"><button id="start">Start GPS</button><button id="stop" disabled>Stop</button></div><div id="status" class="status">Ready. Start GPS before the journey.</div><div class="grid"><div class="readout"><span>Latitude</span><strong id="lat">—</strong></div><div class="readout"><span>Longitude</span><strong id="lng">—</strong></div><div class="readout"><span>Accuracy</span><strong id="accuracy">—</strong></div><div class="readout"><span>Speed</span><strong id="speed">—</strong></div><div class="readout"><span>Heading</span><strong id="heading">—</strong></div><div class="readout"><span>Last sent</span><strong id="sent">—</strong></div></div></main><script>(()=>{const q=id=>document.getElementById(id);let watchId=null,sending=false;const session=()=>q('session').value.trim().toLowerCase();async function send(p){if(sending)return;sending=true;const c=p.coords;q('lat').textContent=c.latitude.toFixed(6);q('lng').textContent=c.longitude.toFixed(6);q('accuracy').textContent=Number.isFinite(c.accuracy)?`±${Math.round(c.accuracy)} m`:'—';q('speed').textContent=Number.isFinite(c.speed)?`${(c.speed*3.6).toFixed(1)} km/h`:'—';q('heading').textContent=Number.isFinite(c.heading)&&c.heading>=0?`${Math.round(c.heading)}°`:'—';try{const r=await fetch('../api/gps.php',{method:'POST',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({session:session(),latitude:c.latitude,longitude:c.longitude,accuracy:c.accuracy,speed:c.speed,heading:c.heading})}),d=await r.json();if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);q('sent').textContent=new Date().toLocaleTimeString();q('status').innerHTML='<span class="ok">GPS LIVE — position sent and journey recorded.</span>';}catch(e){q('status').innerHTML=`<span class="bad">Could not send GPS: ${String(e.message||e)}</span>`;}finally{sending=false;}}function start(){if(watchId!==null)return;const s=session();if(!/^[a-z0-9_-]{3,32}$/.test(s)){q('status').textContent='Invalid session code.';return;}if(!window.isSecureContext||!navigator.geolocation){q('status').textContent='GPS requires HTTPS and browser location support.';return;}q('status').textContent='Requesting precise iPhone location…';q('start').disabled=true;q('stop').disabled=false;q('session').disabled=true;watchId=navigator.geolocation.watchPosition(send,e=>q('status').innerHTML=`<span class="bad">GPS error: ${e.message}</span>`,{enableHighAccuracy:true,timeout:20000,maximumAge:1000});}function stop(){if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;q('start').disabled=false;q('stop').disabled=true;q('session').disabled=false;q('status').textContent='GPS stopped. Recording is saved on RDL.';}q('start').onclick=start;q('stop').onclick=stop;})();</script></body></html>